#include <array>
#include <cstddef>

constexpr bool isPrime(int n)
{
    if (n < 2)
    {
        return false;
    }
    for (int d{ 2 }; d * d <= n; ++d)
    {
        if (n % d == 0)
        {
            return false;
        }
    }
    return true;
}

template <std::size_t N>
constexpr std::array<int, N> firstPrimes()
{
    std::array<int, N> primes{};
    std::size_t found{ 0 };
    for (int candidate{ 2 }; found < N; ++candidate)
    {
        if (isPrime(candidate))
        {
            primes[found++] = candidate;
        }
    }
    return primes;
}

unitTests:
static_assert(isPrime(2) && isPrime(97) && !isPrime(1) && !isPrime(91));
constexpr auto table{ firstPrimes<10>() };
static_assert(table[0] == 2 && table[4] == 11 && table[9] == 29, "the table must be computable at compile time");
static_assert(firstPrimes<100>()[99] == 541);
static_assert(firstPrimes<0>().size() == 0);

TEST("the table is ordinary data at run time") { int sum{ 0 }; for (int p : table) sum += p; CHECK_EQ(sum, 129); }

